{"command":"cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const mode = process.argv.length === 3 ? process.argv[2] : null
function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}
if (mode !== 'rounds' && mode !== 'tally') fail('error: usage: cli.js rounds|tally')

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

let names = null
const known = new Set()
const ballots = []
for (let i = 0; i < lines.length; i++) {
  const n = i + 1
  const t = lines[i].trim()
  if (t === '' || t.startsWith('#')) continue
  const w = t.split(/\s+/)
  const err = (m) => fail(`error: line ${n}: ${m}`)
  if (w[0] === 'candidates') {
    if (names !== null || ballots.length > 0) err('candidates must be declared once, before any ballot')
    if (w.length < 2) err('expected candidates <name>...')
    names = []
    for (const c of w.slice(1)) {
      if (!/^[A-Za-z0-9_-]+$/.test(c)) err(`invalid candidate name ${c}`)
      if (known.has(c)) err(`candidate ${c} is declared twice`)
      known.add(c)
      names.push(c)
    }
  } else if (w[0] === 'ballot') {
    if (names === null) err('candidates must be declared once, before any ballot')
    if (w.length < 3) err('expected ballot <count> <candidate>...')
    if (!/^[1-9][0-9]*$/.test(w[1])) err('count must be a positive integer')
    const seen = new Set()
    for (const c of w.slice(2)) {
      if (!known.has(c)) err(`unknown candidate ${c}`)
      if (seen.has(c)) err(`candidate ${c} is repeated`)
      seen.add(c)
    }
    ballots.push({ count: Number(w[1]), prefs: w.slice(2) })
  } else {
    err(`unknown directive ${w[0]}`)
  }
}
if (names === null) fail('error: no candidates')

const total = ballots.reduce((s, b) => s + b.count, 0)
const continuing = new Set(names)
const history = new Map(names.map((c) => [c, []]))
const out = []
let roundNo = 0
let result = 'no winner'
for (;;) {
  roundNo++
  const counts = new Map([...continuing].map((c) => [c, 0]))
  let active = 0
  for (const b of ballots) {
    const c = b.prefs.find((p) => continuing.has(p))
    if (c !== undefined) {
      counts.set(c, counts.get(c) + b.count)
      active += b.count
    }
  }
  for (const [c, v] of counts) history.get(c).push(v)
  const order = [...counts.keys()].sort((a, b) => counts.get(b) - counts.get(a) || (a < b ? -1 : a > b ? 1 : 0))
  let line = `round ${roundNo}: ` + order.map((c) => `${c}=${counts.get(c)}`).join(' ') + ` exhausted=${total - active}`
  out.push(line)
  if (active === 0) break
  const win = order.find((c) => counts.get(c) * 2 > active)
  if (win !== undefined) {
    result = `winner ${win}`
    break
  }
  let cands = order.slice()
  for (;;) {
    const min = Math.min(...cands.map((c) => counts.get(c)))
    cands = cands.filter((c) => counts.get(c) === min)
    break
  }
  // cands: fewest this round; refine by history
  let pool = cands
  while (pool.length > 1) {
    let k = 0
    for (; k < roundNo; k++) {
      const vs = pool.map((c) => history.get(c)[k])
      if (vs.some((v) => v !== vs[0])) {
        const m = Math.min(...vs)
        pool = pool.filter((c) => history.get(c)[k] === m)
        break
      }
    }
    if (k === roundNo) break
  }
  const elim = pool.reduce((a, b) => (b > a ? b : a))
  continuing.delete(elim)
  out.push(`eliminated ${elim}`)
}
if (mode === 'rounds') process.stdout.write(out.join('\n') + '\n' + result + '\n')
else process.stdout.write(`rounds ${roundNo}\n${result}\n`)
EOF
